package com.anthroid.gateway

import org.json.JSONObject
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.TimeZone

/** A session-less push. sentAtMs is generated by the gateway, never by this UI. */
data class GatewayNotice(
    val title: String,
    val body: String,
    val sender: String? = null,
    val sentAtMs: Long? = null,
) {
    val displaySender: String
        get() = sender?.trim()?.takeIf { it.isNotEmpty() } ?: "Unknown sender"

    fun metadataText(
        locale: Locale = Locale.getDefault(),
        timeZone: TimeZone = TimeZone.getDefault(),
    ): String {
        val sentTime = sentAtMs?.let {
            SimpleDateFormat("yyyy-MM-dd HH:mm:ss z (Z)", locale).apply {
                this.timeZone = timeZone
            }.format(Date(it))
        } ?: "Unknown send time"
        return "From: $displaySender\nSent: $sentTime"
    }

    fun detailText(): String = "${metadataText()}\n\n$body"

    companion object {
        fun fromJson(payload: JSONObject?): GatewayNotice = GatewayNotice(
            title = payload?.optString("title", "Anthroid") ?: "Anthroid",
            body = payload?.optString("body", "") ?: "",
            sender = (payload?.opt("sender") as? String)?.trim()?.takeIf { it.isNotEmpty() },
            // Read only the top-level wire field. Missing/malformed time stays unknown;
            // receiving a push is not evidence of when the gateway sent it.
            sentAtMs = when (val value = payload?.opt("sentAtMs")) {
                is Long -> value
                is Int -> value.toLong()
                else -> null
            },
        )
    }
}
